
function _loader () { echo; printf -v "tmp" "$HOME/tmp"; $@ 2>/dev/null >$tmp/load.log & disown; printf -v pid %b "$!"; printf %b "\e[A\e[K\e[?25l\e[46G\e[K\e[s\n ${re}"; spin='-\|/';     i=0;     while kill -0 $pid 2> /dev/null; do  i=$(( (i+1) %4 ));         printf "\e[A${re} \e[u [${dim}${spin:$i:1} \b${re}] "; kill=y; read -t 0.2 -i "y" "kill"; tail -n1 $tmp/load.log|column --table --columns $((COLUMNS - 52)) --table-columns-limit 1 --table-truncate 0; printf %b "\e[K\r\e[K"; kill -0 $! 2>/dev/null || sudo kill -KILL $pid 2>/dev/null; [ -z "${kill}" ] || sudo kill -KILL $pid; done;     printf "${re} \e[46G [${dim}done \b${re}] ";     printf %b "\n\n"; } 
